 4	export function shouldContinueToolLoop(
 5	  stopReason: string,
 6	  pendingToolCalls: ToolCall[],
 7	  toolRegistry: ToolRegistry | undefined
 8	): boolean {
 9	  return stopReason === 'tool_use' && pendingToolCalls.length > 0 && toolRegistry !== undefined;
10	}
