20	export function buildToolCallMessages(pendingToolCalls: ToolCall[]): Message {
21	  return {
22	    role: 'assistant',
23	    content: pendingToolCalls.map(tc => ({
24	      type: 'tool_use' as const,
25	      toolUseId: tc.id,
26	      name: tc.name,
27	      input: tc.input,
28	    })),
29	  };
30	}
31	
32	export function collectToolCalls(chunk: MessageChunk, pendingToolCalls: ToolCall[]): void {
33	  if (chunk.type === 'tool_use') pendingToolCalls.push(chunk.toolCall);
34	}
35	
36	export function extractStopReason(chunk: MessageChunk): string | null {
37	  return chunk.type === 'stop' ? chunk.stopReason : null;
38	}
39	
40	export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
41	  return chunk.type === 'stop' ? chunk.usage : undefined;
42	}
43	
44	export function accumulateUsage(
45	  total: UsageMetadata | undefined,
46	  incoming: UsageMetadata | undefined
47	): UsageMetadata | undefined {
48	  if (!total) return incoming;
49	  if (!incoming) return total;
50	  return {
51	    inputTokens: total.inputTokens + incoming.inputTokens,
52	    outputTokens: total.outputTokens + incoming.outputTokens,
53	    totalTokens: total.totalTokens + incoming.totalTokens,
54	  };
55	}

